func scanDecTestLine(line string) (contentEnd int, arrow int, directiveColon int, err error) {
	contentEnd = len(line)
	arrow = -1
	directiveColon = -1
	var quote byte

	for index := 0; index < len(line); index++ {
		char := line[index]
		if quote != 0 {
			if char == quote {
				quote = 0
			}
			continue
		}
		if char == '\'' || char == '"' {
			quote = char
			continue
		}
		if char == ':' && directiveColon < 0 {
			directiveColon = index
			continue
		}
		if index+1 >= len(line) || char != '-' {
			continue
		}

		switch line[index+1] {
		case '-':
			return index, arrow, directiveColon, nil
		case '>':
			if arrow >= 0 {
				return 0, 0, 0, errors.New("multiple -> separators")
			}
			arrow = index
			index++
		}
	}

	if quote != 0 {
		return 0, 0, 0, errors.New("unterminated quoted field")
	}
	return contentEnd, arrow, directiveColon, nil
}

func parseDecTestDirectiveInt(directive, value string) (int, error) {
	parsed, err := strconv.Atoi(value)
	if err != nil {
		return 0, fmt.Errorf("invalid %s value %q", directive, value)
	}
	return parsed, nil
}

func normalizeDecTestRounding(value string) (string, error) {
	value = strings.ToLower(strings.TrimSpace(value))
	switch value {
	case "05up", "ceiling", "down", "floor", "half_down", "half_even", "half_up", "up":
		return value, nil
	default:
		return "", fmt.Errorf("invalid rounding value %q", value)
	}
}

// parseDecTestFile parses an IBM decTest file.
func parseDecTestFile(filename string) ([]decTestCase, error) {
	file, err := os.Open(filename)
	if err != nil {
		return nil, fmt.Errorf("open dectest %q: %w", filename, err)
	}
	defer file.Close()

	var cases []decTestCase
	scanner := bufio.NewScanner(file)

	// Default context values
	rounding := "half_even"
	precision := 9
	maxExponent := 384
	minExponent := -383
	clamp := 0

	lineNumber := 0
	for scanner.Scan() {
		lineNumber++
		line := strings.TrimSpace(scanner.Text())

		// Skip comments and empty lines
		if line == "" || strings.HasPrefix(line, "--") {
			continue
		}

		contentEnd, arrow, directiveColon, err := scanDecTestLine(line)
		if err != nil {
			return nil, fmt.Errorf("parse dectest %q line %d: %w", filename, lineNumber, err)
		}
		if directiveColon >= 0 && arrow >= 0 && directiveColon < arrow {
			return nil, fmt.Errorf("parse dectest %q line %d: directive must not contain a -> separator", filename, lineNumber)
		}

		// Parse test cases (format: id operation operand... -> result flags)
		if arrow >= 0 {
			leftPart := splitDecTestFields(line[:arrow])
			rightPart := splitDecTestFields(line[arrow+2 : contentEnd])

			if len(leftPart) < 3 || len(rightPart) < 1 {
				return nil, fmt.Errorf("parse dectest %q line %d: case requires an id, operation, at least one operand, and result", filename, lineNumber)
			}

			tc := decTestCase{
				ID:           leftPart[0],
				Operation:    leftPart[1],
				Operands:     leftPart[2:],
				Result:       rightPart[0],
				RoundingMode: rounding,
				Precision:    precision,
				MaxExponent:  maxExponent,
				MinExponent:  minExponent,
				Clamp:        clamp,
			}

			// Extract flags
			if len(rightPart) > 1 {
				tc.Flags = rightPart[1:]
			}

			cases = append(cases, tc)
			continue
		}

		content := strings.TrimSpace(line[:contentEnd])
		if content == "" {
			continue
		}
		if directiveColon < 0 {
			return nil, fmt.Errorf("parse dectest %q line %d: unexpected content %q", filename, lineNumber, content)
		}

		directive := strings.ToLower(strings.TrimSpace(content[:directiveColon]))
		value := strings.TrimSpace(content[directiveColon+1:])
		switch directive {
		case "rounding":
			rounding, err = normalizeDecTestRounding(value)
		case "precision":
			precision, err = parseDecTestDirectiveInt(directive, value)
			if err == nil && precision <= 0 {
				err = fmt.Errorf("precision must be positive, got %d", precision)
			}
		case "maxexponent":
			maxExponent, err = parseDecTestDirectiveInt(directive, value)
		case "minexponent":
			minExponent, err = parseDecTestDirectiveInt(directive, value)
		case "clamp":
			clamp, err = parseDecTestDirectiveInt(directive, value)
			if err == nil && clamp != 0 && clamp != 1 {
				err = fmt.Errorf("clamp must be 0 or 1, got %d", clamp)
			}
		case "extended":
			var extended int
			extended, err = parseDecTestDirectiveInt(directive, value)
			if err == nil && extended != 0 && extended != 1 {
				err = fmt.Errorf("extended must be 0 or 1, got %d", extended)
			}
		case "version", "dectest":
			if value == "" {
				err = fmt.Errorf("%s value must not be empty", directive)
			}
		default:
			err = fmt.Errorf("unknown directive %q", directive)
		}
		if err != nil {
			return nil, fmt.Errorf("parse dectest %q line %d: %w", filename, lineNumber, err)
		}
	}

	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("scan dectest %q: %w", filename, err)
	}
	return cases, nil
}

// compareDecimalResults compares two decimal result strings with decTest rules
func compareDecimalResults(expected, actual string) bool {
	if normalizeDecimalResult(expected) == normalizeDecimalResult(actual) {
		return true
	}

	left, leftOK := parseComparableDecimal(expected)
	right, rightOK := parseComparableDecimal(actual)
	if !leftOK || !rightOK {
		return false
	}
	return comparableDecimalResultsEqual(left, right)
}

func comparableDecimalResultsEqual(left, right decTestComparableDecimal) bool {
	if left.special != right.special {
		return false
	}

	switch left.special {
	case decTestSpecialNone:
		if left.isZero || right.isZero {
			return left.isZero && right.isZero && left.sign == right.sign
		}
		return left.sign == right.sign && left.digits == right.digits && left.exponent == right.exponent
	case decTestSpecialInfinity:
		return left.sign == right.sign
	case decTestSpecialQuietNaN, decTestSpecialSignalingNaN:
		return left.nanSign == right.nanSign && left.payload == right.payload
	case decTestSpecialInvalidSyntax:
		return true
	default:
		return false
	}
}

// getBaseName returns the base name of a file
func getBaseName(filename string) string {
	base := strings.TrimSuffix(filename, ".decTest")
	lastSlash := strings.LastIndex(base, "/")
	if lastSlash != -1 {
		base = base[lastSlash+1:]
	}
	return base
}

func normalizeDecTestOperation(op string) string {
	op = strings.TrimSpace(strings.ToLower(op))
	return strings.ReplaceAll(op, "_", "")
}

func decTestSkipReason(ignoredOperations []string, tc decTestCase, testType string) (string, bool) {
	if shouldSkipDectestIgnoredOperation(ignoredOperations, tc.Operation) {
		return "ignored_operation_" + normalizeDecTestOperation(tc.Operation), true
	}
	if reason, ok := decTestCaseSkipReason(tc, testType); ok {
		return reason, true
	}
	if reason, ok := decTestFlagSkipReason(tc); ok {
		return reason, true
	}
	return "", false
}

func shouldSkipDecTestCase(tc decTestCase, testType string) bool {
	_, ok := decTestCaseSkipReason(tc, testType)
	return ok
}

func decTestCaseSkipReason(tc decTestCase, testType string) (string, bool) {
	if (testType == "general" || testType == "decimal128") && usesTaggedDecTestLiteral(tc) {
		return "tagged_literal", true
	}
	if isTaggedToIntegralCase(tc) {
		return "tagged_to_integral", true
	}
	if isUnsupportedNextTowardNaNPayloadPrecedenceCase(tc, testType) {
		return "nexttoward_nan_payload_precedence", true
	}
	if isUnsupportedMinMaxZeroTieCase(tc, testType) {
		return "minmax_zero_tie", true
	}
	if isUnsupportedMinMaxNaNPayloadPrecedenceCase(tc, testType) {
		return "minmax_nan_payload_precedence", true
	}
	if reason, ok := unsupportedFMADecTestReason(tc, testType); ok {
		return reason, true
	}
	if reason, ok := unsupportedRemainderFamilyDecTestReason(tc, "remainder", testType); ok {
		return reason, true
	}
	if reason, ok := unsupportedRemainderFamilyDecTestReason(tc, "remaindernear", testType); ok {
		return reason, true
	}

	switch testType {
	case "decimal32":
		if tc.Precision > 7 {
			return "precision_over_decimal32", true
		}
	case "decimal64":
		if tc.Precision > 16 {
			return "precision_over_decimal64", true
		}
	case "decimal128":
		if tc.Precision > 34 {
			return "precision_over_decimal128", true
		}
	case "general":
		if tc.Precision > 34 {
			return "precision_over_general", true
		}
	default:
		return "unsupported_test_type", true
	}
	return "", false
}

func unsupportedFMADecTestReason(tc decTestCase, testType string) (string, bool) {
	if normalizeDecTestOperation(tc.Operation) != "fma" {
		return "", false
	}
	if _, ok := decTestBIDRoundingMode(tc.RoundingMode); !ok {
		return "fma_unsupported_rounding", true
	}
	if isUnsupportedFMANaNPayloadPrecedenceCase(tc, testType) {
		return "fma_nan_payload_precedence", true
	}
	return "", false
}

func hasDecTestFlag(flags []string, want string) bool {
	normalizedWant := normalizeDecTestFlag(want)
	for _, flag := range flags {
		if normalizeDecTestFlag(flag) == normalizedWant {
			return true
		}
	}
	return false
}

func unsupportedRemainderFamilyDecTestReason(tc decTestCase, operation, testType string) (string, bool) {
	if normalizeDecTestOperation(tc.Operation) != operation {
		return "", false
	}
	if isIntelLeftNaNGDARightNaNIdentityDivergence(tc, testType) {
		return operation + "_nan_payload_precedence", true
	}
	if !hasOnlyFiniteDecTestOperands(tc, 2) {
		return "", false
	}
	if hasOnlyDecTestCondition(tc.Flags, "divisionimpossible") && isDefaultQuietDecTestNaN(tc.Result) {
		return operation + "_gda_division_impossible_context_semantics", true
	}
	return "", false
}

func hasOnlyFiniteDecTestOperands(tc decTestCase, count int) bool {
	if len(tc.Operands) != count {
		return false
	}
	for _, operand := range tc.Operands {
		parsed, ok := parseComparableDecimal(operand)
		if !ok || parsed.special != decTestSpecialNone {
			return false
		}
	}
	return true
}

func isFiniteDecTestValue(input string) bool {
	parsed, ok := parseComparableDecimal(input)
	return ok && parsed.special == decTestSpecialNone
}

func isDefaultQuietDecTestNaN(input string) bool {
	info := parseDecTestNaNOperand(input)
	return info.isNaN && !info.signaling && info.sign == "+" && info.payload == ""
}

func isUnsupportedNextTowardNaNPayloadPrecedenceCase(tc decTestCase, testType string) bool {
	if normalizeDecTestOperation(tc.Operation) != "nexttoward" || len(tc.Operands) != 2 {
		return false
	}
	return isIntelLeftNaNGDARightNaNIdentityDivergence(tc, testType)
}

func isIntelLeftNaNGDARightNaNIdentityDivergence(tc decTestCase, testType string) bool {
	if len(tc.Operands) != 2 {
		return false
	}
	left := parseDecTestNaNOperand(tc.Operands[0])
	right := parseDecTestNaNOperand(tc.Operands[1])
	expected := parseDecTestNaNOperand(tc.Result)
	if !left.isNaN || left.signaling || !right.isNaN || !right.signaling ||
		!expected.isNaN || expected.signaling ||
		!decTestNaNPayloadFitsType(left, testType) ||
		!decTestNaNPayloadFitsType(right, testType) ||
		!decTestNaNPayloadFitsType(expected, testType) ||
		!hasOnlyInvalidOperationDecTestCondition(tc.Flags) {
		return false
	}
	// GDA quietizes the right signaling NaN. These pinned Intel BID operations
	// return the left quiet NaN after signaling invalid. Skip only when the
	// authoritative GDA result and Intel identity genuinely differ.
	if expected.sign != right.sign || expected.payload != right.payload {
		return false
	}
	return left.sign != expected.sign || left.payload != expected.payload
}

func isUnsupportedMinMaxZeroTieCase(tc decTestCase, testType string) bool {
	if !isMinMaxDecTestOperation(tc.Operation) || len(tc.Operands) != 2 ||
		!hasOnlyDecTestConditions(tc.Flags) {
		return false
	}
	left, leftOK := parseComparableDecimal(tc.Operands[0])
	right, rightOK := parseComparableDecimal(tc.Operands[1])
	if !leftOK || !rightOK || left.special != decTestSpecialNone || right.special != decTestSpecialNone ||
		!left.isZero || !right.isZero || left.sign == right.sign {
		return false
	}

	selected, ok := intelMinMaxZeroTieSelectedOperand(tc.Operation, testType)
	if !ok {
		return false
	}
	expected, expectedOK := parseComparableDecimal(tc.Result)
	if !expectedOK || expected.special != decTestSpecialNone || !expected.isZero {
		return false
	}
	operands := [2]decTestComparableDecimal{left, right}
	return operands[selected].sign != expected.sign
}

func intelMinMaxZeroTieSelectedOperand(operation, testType string) (int, bool) {
	// Pinned Intel BID C returns a fixed operand when both coefficients are
	// zero. Keep this source-derived rule independent of the Go implementation
	// so a regression in the implementation still fails every non-divergent row.
	switch testType {
	case "decimal32", "decimal64":
		switch normalizeDecTestOperation(operation) {
		case "min", "max", "maxmag":
			return 1, true
		case "minmag":
			return 0, true
		}
	case "decimal128":
		switch normalizeDecTestOperation(operation) {
		case "min", "max", "minmag":
			return 0, true
		case "maxmag":
			return 1, true
		}
	}
	return 0, false
}

func isUnsupportedMinMaxNaNPayloadPrecedenceCase(tc decTestCase, testType string) bool {
	if !isMinMaxDecTestOperation(tc.Operation) || len(tc.Operands) != 2 {
		return false
	}
	return isIntelLeftNaNGDARightNaNIdentityDivergence(tc, testType)
}

func decTestNaNPayloadFitsType(info decTestNaNOperand, testType string) bool {
	var maxDigits int
	switch testType {
	case "decimal32":
		maxDigits = 6
	case "decimal64":
		maxDigits = 15
	case "decimal128":
		maxDigits = 33
	default:
		return false
	}
	return len(info.payload) <= maxDigits
}

func hasOnlyInvalidOperationDecTestCondition(flags []string) bool {
	return hasOnlyDecTestCondition(flags, "invalidoperation")
}

func hasOnlyDecTestCondition(flags []string, want string) bool {
	return hasOnlyDecTestConditions(flags, want)
}

func hasOnlyDecTestConditions(flags []string, wants ...string) bool {
	if len(flags) != len(wants) {
		return false
	}
	matched := make([]bool, len(wants))
	for _, flag := range flags {
		normalized := normalizeDecTestFlag(flag)
		found := false
		for i, want := range wants {
			if !matched[i] && normalized == normalizeDecTestFlag(want) {
				matched[i] = true
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	return true
}

// isUnsupportedFMANaNPayloadPrecedenceCase reports fma cases where GDA decTest
// NaN propagation (first signaling NaN in operand order x, y, z; otherwise the
// first quiet NaN) selects a different NaN identity (sign plus payload) than
// the Intel BID port, which propagates the first NaN it unpacks in y, z, x
// order (bid-go fma64/bid128_fma NaN unpack order). When both rules pick the
// same identity the case runs; only genuinely divergent identities are skipped.
func isUnsupportedFMANaNPayloadPrecedenceCase(tc decTestCase, testType string) bool {
	if len(tc.Operands) != 3 {
		return false
	}
	var infos [3]decTestNaNOperand
	for i := range tc.Operands {
		infos[i] = parseDecTestNaNOperand(tc.Operands[i])
		if infos[i].isNaN {
			if !decTestNaNPayloadFitsType(infos[i], testType) {
				return false
			}
			continue
		}
		parsed, ok := parseComparableDecimal(tc.Operands[i])
		if !ok || parsed.special != decTestSpecialNone && parsed.special != decTestSpecialInfinity {
			return false
		}
	}
	gda := -1
	for i := range infos {
		if infos[i].isNaN && infos[i].signaling {
			gda = i
			break
		}
	}
	if gda < 0 {
		for i := range infos {
			if infos[i].isNaN {
				gda = i
				break
			}
		}
	}
	if gda < 0 {
		return false
	}
	intel := -1
	for _, i := range [3]int{1, 2, 0} {
		if infos[i].isNaN {
			intel = i
			break
		}
	}
	if intel < 0 {
		return false
	}
	expected := parseDecTestNaNOperand(tc.Result)
	if !expected.isNaN || expected.signaling || !decTestNaNPayloadFitsType(expected, testType) ||
		expected.sign != infos[gda].sign || expected.payload != infos[gda].payload {
		return false
	}
	if infos[gda].signaling {
		if !hasOnlyInvalidOperationDecTestCondition(tc.Flags) {
			return false
		}
	} else if !hasOnlyDecTestConditions(tc.Flags) {
		return false
	}
	return infos[gda].sign != infos[intel].sign || infos[gda].payload != infos[intel].payload
}

type decTestNaNOperand struct {
	isNaN     bool
	signaling bool
	sign      string
	payload   string
}

// parseDecTestNaNOperand extracts the quietized NaN identity of a decTest
// operand literal: sign and payload digits with leading zeros stripped, so
// "-sNaN00" and "-NaN" compare equal after quietization.
func parseDecTestNaNOperand(input string) decTestNaNOperand {
	trimmed := strings.TrimSpace(decTestOperandString(input))
	sign := "+"
	if strings.HasPrefix(trimmed, "-") {
		sign = "-"
		trimmed = trimmed[1:]
	} else {
		trimmed = strings.TrimPrefix(trimmed, "+")
	}
	lower := strings.ToLower(trimmed)
	info := decTestNaNOperand{sign: sign}
	var payload string
	switch {
	case strings.HasPrefix(lower, "snan"):
		info.isNaN = true
		info.signaling = true
		payload = lower[len("snan"):]
	case strings.HasPrefix(lower, "nan"):
		info.isNaN = true
		payload = lower[len("nan"):]
	default:
		return decTestNaNOperand{}
	}
	for _, r := range payload {
		if r < '0' || r > '9' {
			return decTestNaNOperand{}
		}
	}
	info.payload = strings.TrimLeft(payload, "0")
	return info
}

func isMinMaxDecTestOperation(op string) bool {
	switch normalizeDecTestOperation(op) {
	case "min", "max", "minmag", "maxmag":
		return true
	default:
		return false
	}
}

func isQuietDecTestNaN(input string) bool {
	info := parseDecTestNaNOperand(input)
	return info.isNaN && !info.signaling
}

func isSignalingDecTestNaN(input string) bool {
	info := parseDecTestNaNOperand(input)
	return info.isNaN && info.signaling
}

func isTaggedToIntegralCase(tc decTestCase) bool {
	op := normalizeDecTestOperation(tc.Operation)
	if op != "tointegral" && op != "tointegralx" {
		return false
	}
	return usesTaggedDecTestLiteral(tc)
}

func usesTaggedDecTestLiteral(tc decTestCase) bool {
	for _, operand := range tc.Operands {
		if strings.Contains(operand, "#") {
			return true
		}
	}
	return strings.Contains(tc.Result, "#")
}

func shouldSkipDecTestFlags(tc decTestCase) bool {
	_, ok := decTestFlagSkipReason(tc)
	return ok
}

func decTestFlagSkipReason(tc decTestCase) (string, bool) {
	if supportsDecTestFlagVerification() {
		return "", false
	}

	op := normalizeDecTestOperation(tc.Operation)
	if op != "add" && op != "subtract" && op != "multiply" && op != "divide" {
		return "", false
	}

	for _, flag := range tc.Flags {
		switch normalizeDecTestFlag(flag) {
		case "clamped", "divisionundefined":
			return "unsupported_flag_" + normalizeDecTestFlag(flag), true
		}
	}
	return "", false
}

func shouldSkipDectestIgnoredOperation(ignoredOperations []string, operation string) bool {
	normalized := normalizeDecTestOperation(operation)
	for _, ignored := range ignoredOperations {
		if normalizeDecTestOperation(ignored) == normalized {
			return true
		}
	}
	return false
}

// testWithDecTestV2 runs the IBM decTest files under testDir.
func testWithDecTestV2(testDir string) error {
	testSuites, err := loadGeneratedDectestRunSuites()
	if err != nil {
		return fmt.Errorf("load generated dectest suites: %w", err)
	}

	totalResults := make(map[string]map[string]int)
	var suiteTotals []decTestSuiteTotals

	// Run each test suite
	for _, suite := range testSuites {
		fmt.Printf("\n=== Running %s Tests ===\n", suite.Name)

		suiteResults := make(map[string]int)
		totalPassed := 0
		totalFailed := 0
		totalSkipped := 0

		for _, generatedFile := range suite.Files {
			testFile := filepath.Join(testDir, filepath.Base(generatedFile))
			base := getBaseName(testFile)

			cases, err := parseDecTestFile(testFile)
			if err != nil {
				fmt.Printf("Failed to parse %s: %v\n", testFile, err)
				continue
			}

			passed := 0
			failed := 0
			skipped := 0

			for _, tc := range cases {
				if _, ok := decTestSkipReason(suite.IgnoredOperations, tc, suite.TestType); ok {
					skipped++
					continue
				}

				err := runDecTestCaseV2(tc, suite.TestType)
				if err != nil {
					if errors.Is(err, errUnsupportedDecTestOperation) || strings.Contains(err.Error(), "unsupported") {
						skipped++
					} else {
						failed++
						if failed < 5 { // Only show first 5 failures per file
							fmt.Printf("FAIL %s: %v\n", tc.ID, err)
						}
					}
				} else {
					passed++
				}
			}

			if passed+failed+skipped > 0 {
				fmt.Printf("%s: %d passed, %d failed, %d skipped (total: %d)\n",
					base, passed, failed, skipped, passed+failed+skipped)
			}

			suiteResults[base] = passed
			totalPassed += passed
			totalFailed += failed
			totalSkipped += skipped
		}

		if totalPassed+totalFailed+totalSkipped > 0 {
			fmt.Printf("Suite %s Total: %d passed, %d failed, %d skipped\n",
				suite.Name, totalPassed, totalFailed, totalSkipped)
		}

		suiteTotals = append(suiteTotals, decTestSuiteTotals{
			Name:    suite.Name,
			Passed:  totalPassed,
			Failed:  totalFailed,
			Skipped: totalSkipped,
		})
		totalResults[suite.Name] = suiteResults
	}

	// Print summary
	fmt.Printf("\n=== New Type System decTest Summary ===\n")
	for suiteName, results := range totalResults {
		fmt.Printf("%s:\n", suiteName)
		for testName, passed := range results {
			fmt.Printf("  %s: %d passed\n", testName, passed)
		}
	}

	return decTestFailureError(suiteTotals)
}

func decTestFailureError(suites []decTestSuiteTotals) error {
	totalFailed := 0
	parts := make([]string, 0, len(suites))

	for _, suite := range suites {
		totalFailed += suite.Failed
		if suite.Failed > 0 {
			parts = append(parts, fmt.Sprintf("%s=%d", suite.Name, suite.Failed))
		}
	}

	if totalFailed == 0 {
		return nil
	}

	return fmt.Errorf("decTest failures detected (%d total): %s", totalFailed, strings.Join(parts, ", "))
}

func compareDecTestFlags(expected []string, actual ExceptionFlags) bool {
	expectedFlags, ok := parseDecTestFlags(expected)
	if !ok {
		return false
	}
	return expectedFlags == actual
}

func compareDecTestBIDFiveFlags(expected []string, actual ExceptionFlags) bool {
	expectedFlags, ok := parseDecTestFlags(expected)
	if !ok {
		return false
	}
	// Intel BID exposes only these five exception flags. IBM GDA conditions
	// such as Rounded, Subnormal, and Clamped are parsed for validation but are
	// outside this differential comparison surface.
	const bidFlagMask = FlagInvalidOperation | FlagDivisionByZero | FlagOverflow | FlagUnderflow | FlagInexact
	return expectedFlags&bidFlagMask == actual&bidFlagMask
}

func parseDecTestFlags(flags []string) (ExceptionFlags, bool) {
	var parsed ExceptionFlags
	for _, flag := range flags {
		switch normalizeDecTestFlag(flag) {
		case "", "none", "noflags":
			continue
		case "inexact":
			parsed |= FlagInexact
		case "underflow":
			parsed |= FlagUnderflow
		case "overflow":
			parsed |= FlagOverflow
		case "divisionbyzero":
			parsed |= FlagDivisionByZero
		case "invalidoperation", "divisionundefined", "divisionimpossible", "insufficientstorage", "conversionsyntax":
			parsed |= FlagInvalidOperation
		case "subnormal":
			parsed |= FlagSubnormal
		case "rounded":
			parsed |= FlagRounded
		case "clamped":
			parsed |= FlagClamped
		default:
			return 0, false
		}
	}
	return parsed, true
}

func normalizeDecTestFlag(flag string) string {
	flag = strings.Trim(flag, "'\"")
	flag = strings.ToLower(flag)
	flag = strings.ReplaceAll(flag, "_", "")
	flag = strings.ReplaceAll(flag, "-", "")
	flag = strings.ReplaceAll(flag, " ", "")
	return flag
}

func splitDecTestFields(input string) []string {
	var fields []string
	var current strings.Builder
	var quote rune

	flush := func() {
		if current.Len() == 0 {
			return
		}
		fields = append(fields, current.String())
		current.Reset()
	}

	for _, r := range input {
		switch {
		case quote != 0:
			current.WriteRune(r)
			if r == quote {
				quote = 0
			}
		case r == '\'' || r == '"':
			current.WriteRune(r)
			quote = r
		case r == ' ' || r == '\t':
			flush()
		default:
			current.WriteRune(r)
		}
	}

	flush()
	return fields
}

